reversal.fixed_text:
'\u{FFFD}' => {
    let bytes = self[s..e].as_bytes();
    if bytes == b"\xEF\xBF\xBD" {
        write!(f, "{}", ch.escape_debug())?;
    } else {
        for &b in self[s..e].as_bytes() {
            write!(f, r"\x{:02X}", b)?;
        }
    }
}

